import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes, Link } from 'react-router-dom'; // Cambié 'Switch' por 'Routes'
import './App.css';
import Login from './auth/Login';
import Registro from './auth/Registro';
import AdminPanel from './admin/AdminPanel';
import { FaShoppingCart } from 'react-icons/fa'; 

function App() {
  const [cartItems, setCartItems] = useState([]);
  const productos = [
    { id: 1, nombre: 'Accesorio 1', precio: 1000, imagen: 'https://via.placeholder.com/150.png?text=Producto+1' },
    { id: 2, nombre: 'Accesorio 2', precio: 1500, imagen: 'https://via.placeholder.com/150.png?text=Producto+2' },
    { id: 3, nombre: 'Accesorio 3', precio: 2000, imagen: 'https://via.placeholder.com/150.png?text=Producto+3' },
  ];

  const agregarAlCarrito = (producto) => {
    setCartItems([...cartItems, producto]);
  };

  return (
    <Router>
      <div className="container">
        {/* Navbar */}
        <nav className="navbar">
          <div className="navbar-links">
            <a href="#">¿Quiénes Somos?</a>
            <a href="#">Comercialización</a>
            <a href="#">Sucursales</a>
            <a href="#">Contáctenos</a>
          </div>
          <div className="navbar-account">
            <Link to="/login">
              <button>Mi Cuenta</button>
            </Link>
            <Link to="/carrito" className="cart-icon">
              <FaShoppingCart size={20} />
              {cartItems.length > 0 && <span className="cart-count">{cartItems.length}</span>}
            </Link>
          </div>
        </nav>

        {/* Rutas de la página */}
        <Routes>
          <Route 
            path="/" 
            element={
              <div>
                {/* Header */}
                <div className="header">
                  <div className="logo">
                    <span>Mi Tienda</span>
                  </div>

                  {/* Barra de búsqueda */}
                  <div className="search-bar">
                    <input type="text" placeholder="Buscar productos..." />
                    <button>Buscar</button>
                  </div>
                </div>
                {/* Categorías */}
                <div className="categories">
                  {['Celulares', 'Smartwatch', 'Auriculares', 'Cargadores', 'Memorias SD'].map((item) => (
                    <div key={item} className="category">
                      <div className="icon">📱</div>
                      <span>{item}</span>
                    </div>
                  ))}
                </div>

                {/* Banner */}
                <div className="banner">
                  <img 
                    src="http://t.ctcdn.com.br/9uPzXT2-oXWYbmRWWb4LzmRMf4U=/1200x675/smart/i867445.png" 
                    alt="Promocional"
                  />
                </div>

                {/* Ofertas */}
                <div className="offers">
                  <h2>Productos</h2>
                  <div className="products">
                    {productos.map((producto) => (
                      <div key={producto.id} className="product-card">
                        <img 
                          src={producto.imagen} 
                          alt={producto.nombre} 
                        />
                        <h3>{producto.nombre}</h3>
                        <p>${producto.precio}</p>
                        <button 
                          className="add-to-cart-button" 
                          onClick={() => agregarAlCarrito(producto)}
                        >
                          Agregar al carrito
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            }
          />
          <Route path="/login" element={<Login />} />
          <Route path="/registro" element={<Registro />} />
          <Route path="/admin" element={<AdminPanel />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
